<?php
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');require_once __DIR__.'/config/conexion.php';require_once __DIR__.'/config/seguridad.php';
try{$u=tm_require_roles($conexion,['Jefe','Administrador','Empleado']);tm_require_same_origin_for_post();if($_SERVER['REQUEST_METHOD']!=='POST')tm_json_error(405,'Método no permitido.');if(empty($_FILES['imagen'])||$_FILES['imagen']['error']!==UPLOAD_ERR_OK)tm_json_error(422,'Selecciona una imagen válida.');$f=$_FILES['imagen'];if($f['size']>4*1024*1024)tm_json_error(422,'La imagen debe pesar máximo 4 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$exts=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];if(!isset($exts[$mime]))tm_json_error(422,'Formatos permitidos: JPG, PNG, WEBP o GIF.');$dir=__DIR__.'/uploads/productos';if(!is_dir($dir)&&!mkdir($dir,0755,true))tm_json_error(500,'No se pudo crear la carpeta de imágenes.');$name=bin2hex(random_bytes(16)).'.'.$exts[$mime];if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))tm_json_error(500,'No se pudo guardar la imagen.');echo json_encode(['ok'=>true,'url'=>'uploads/productos/'.$name]);}catch(Throwable $e){error_log('TechMarket image upload: '.$e->getMessage());if(!headers_sent())tm_json_error(500,'No se pudo subir la imagen.');}
